-- Import 12 článků ze starého tenishub.cz (WP export 2025-09-25) → Knihovna /clanky.
-- Bezpečné: ON CONFLICT (slug) DO NOTHING (klidně spustit víckrát). Obrázky odkazují na starý web (běží dál).
-- is_sample=false → článek je HUB+ (nečlen vidí ochutnávku + bránu). Ochutnávky si označíš v adminu.

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'jak-na-prestup-nebo-hostovani-v-tenise-prakticky-pruvodce-pro-rodice', 'Jak na přestup nebo hostování v tenise? Praktický průvodce pro rodiče', 'Hostování hráčů v soutěžích družstev Obecné podmínky: Hráč smí v jednom kalendářním roce hostovat pouze v jednom jiném klubu . Hostování je povoleno pouze v soutěžích družstev…',
  '<h3>Hostování hráčů v soutěžích družstev</h3><ol><li><p><strong>Obecné podmínky:</strong></p><ul><li><p>Hráč smí v jednom kalendářním roce hostovat pouze v <strong>jednom jiném klubu</strong>.</p></li><li><p>Hostování je <strong>povoleno pouze v soutěžích družstev</strong> (mládež nebo dospělí).</p></li><li><p>Hráč může zároveň:<br />- hrát za <strong>mateřský klub</strong> v jedné věkové kategorii,<br />- <strong>hostovat</strong> v jiné věkové kategorii za jiný klub.</p></li></ul></li><li><p><strong>Administrativní náležitosti:</strong></p><ul><li><p>Hostování musí být <strong>řádně zaregistrováno</strong> u příslušného oblastního nebo republikového svazu.</p></li><li><p>Hostování musí být doloženo <strong>písemným souhlasem mateřského klubu</strong>.</p></li><li><p>Je možné <strong>časové omezení hostování</strong> (např. na konkrétní část sezony).</p></li></ul></li><li><p><strong>Omezení:</strong></p><ul><li><p>Hostující hráč <strong>nesmí nastoupit proti svému mateřskému klubu</strong>.</p></li><li><p>Hráč <strong>nesmí být na soupisce dvou různých klubů</strong> ve stejné věkové kategorii.</p></li></ul></li></ol><h3>Přestup mezi kluby</h3><ol><li><p><strong>Obecné zásady:</strong></p><ul><li><p>Přestup hráče je přechod z jednoho registrovaného klubu Českého tenisového svazu (ČTS) do druhého.</p></li><li><p>Přestup je umožněn <strong>v souladu s platným soutěžním řádem a přestupním řádem ČTS</strong>.</p></li></ul></li><li><p><strong>Podmínky přestupu:</strong></p><ul><li><p>Hráč může přestoupit <strong>v určeném přestupním období</strong> (většinou v první části kalendářního roku – dle vyhlášky ČTS).</p></li><li><p>Přestup je <strong>platný až po schválení a zaregistrování ČTS</strong>.</p></li><li><p>Přestupový formulář musí obsahovat:</p><ul><li><p>údaje o hráči,</p></li><li><p>původní klub,</p></li><li><p>nový klub,</p></li><li><p>podpisy zástupců obou klubů,</p></li><li><p>případné vyjádření hráče/zákonného zástupce (u mládeže).</p></li></ul></li></ul></li><li><p><strong>Omezení:</strong></p><ul><li><p>V jednom roce je zpravidla možný pouze <strong>jeden přestup</strong>.</p></li><li><p>Hráč <strong>nesmí nastoupit v soutěžích</strong> za nový klub, dokud není přestup potvrzen ČTS.</p></li><li><p>Pokud se kluby <strong>nedomluví</strong>, je možné podat žádost k rozhodnutí přestupní komise.</p></li></ul></li><li><p><strong>Poplatky:</strong></p><ul><li><p>Za přestup může být vybírán administrativní poplatek dle sazebníku ČTS.</p></li></ul></li></ol>',
  'navody', 'Jiří Machek', false, true, '2025-08-24 15:29:47'
) on conflict (slug) do nothing;

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'zakladni-pravidla-tenisu-prehled-pro-hrace-i-trenery', 'Základní pravidla tenisu: Přehled pro hráče i trenéry', 'Tenis je hra plná přesnosti, taktiky a fair play. Ať už jste začátečník, rodič malého tenisty nebo začínající trenér, tento přehled vám pomůže rychle se zorientovat v klíčových…',
  '<p>Tenis je hra plná přesnosti, taktiky a fair play. Ať už jste začátečník, rodič malého tenisty nebo začínající trenér, tento přehled vám pomůže rychle se zorientovat v klíčových pravidlech a principech hry.<br><br></p> <hr> <h5><img role="img" draggable="false" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f3df.svg" alt="🏟"> Rozměry kurtu</h5> <ul> <li> <p><strong>Dvouhra:</strong> 23,77 m × 8,23 m</p></li> <li> <p><strong>Čtyřhra:</strong> 23,77 m × 10,97 m</p></li> <li> <p><strong>Síť:</strong></p> <ul> <li> <p>Výška u sloupků: <strong>1,07 m</strong></p></li> <li> <p>Uprostřed: <strong>0,914 m</strong></p></li></ul></li></ul> <p><strong>Čáry na kurtu:</strong><br>Základní čára, postranní čáry, čáry pro podání, středová značka.<br>→ Všechny čáry musí být <strong>bílé a dobře viditelné</strong>.<br><br></p> <hr> <h5><img role="img" draggable="false" src="https://s.w.org/images/core/emoji/16.0.1/svg/23f1.svg" alt="⏱"> Počítání bodů</h5> <p>a) <strong>Standardní hra</strong></p> <p>Pořadí: <strong>0 – 15 – 30 – 40 – hra</strong><br>Při shodě: <strong>"Výhoda"</strong> – hráč musí získat <strong>2 body v řadě</strong>.</p> <p>b) <strong>Tie-break</strong></p> <ul> <li> <p>Hraje se do <strong>7 bodů</strong>, rozdíl minimálně <strong>2 body</strong>.</p></li> <li> <p>Pořadí podání: <strong>1 – 2 – 2 – 2...</strong></p></li> <li> <p>Strany se mění <strong>každých 6 bodů</strong>.</p></li></ul> <p>c) <strong>Sady</strong></p> <ul> <li> <p>Hraje se na <strong>6 her</strong> s rozdílem 2.</p></li> <li> <p>Při stavu <strong>6:6</strong>: buď tie-break, nebo pokračování do rozdílu 2 her (dle domluvy).<br><br></p></li></ul> <hr> <h5><img role="img" draggable="false" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f680.svg" alt="🚀"> Podání</h5> <ul> <li> <h6>Podává se <strong>za základní čárou</strong>, střídavě zprava a zleva.</h6></li> <li> <p><strong>Chyba nohou:</strong> dotyk čáry nebo špatné postavení = chyba.</p></li> <li> <p>Každý hráč má <strong>2 pokusy</strong>.</p></li> <li> <p>Podání musí dopadnout <strong>úhlopříčně do podávacího pole</strong>.</p></li> <li> <p><strong>Dotyk sítě</strong> nebo letmý kontakt míče = chyba.<br><br></p></li></ul> <hr> <h5><img role="img" draggable="false" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f504.svg" alt="🔄"> Střídání stran</h5> <ul> <li> <p>Po <strong>1., 3.</strong> a každé další <strong>liché hře</strong>.</p></li> <li> <p>Po <strong>každé sadě</strong>, pokud počet her v sadě je sudý → změna po <strong>1. hře nové sady</strong>.</p></li> <li> <p>V tie-breaku: <strong>každých 6 bodů</strong>.<br><br></p></li></ul> <hr> <h5><img role="img" draggable="false" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f501.svg" alt="🔁"> Míč ve hře a hodnocení</h5> <ul> <li> <p>Míč je ve hře od podání až do konce výměny.</p></li> <li> <p><strong>Míč na čáře = platný</strong>.</p></li> <li> <p><strong>Dotyk sítě</strong> před dopadem = bod pro soupeře.<br><br></p></li></ul> <hr> <h5><img role="img" draggable="false" src="https://s.w.org/images/core/emoji/16.0.1/svg/274c.svg" alt="❌"> Ztráta bodu – kdy?</h5> <p>Například pokud hráč:</p> <ul> <li> <p>Nevrátí míč správně.</p></li> <li> <p>Udělá <strong>dvojchybu</strong> při podání.</p></li> <li> <p>Dotkne se <strong>sítě, sloupků nebo soupeřova pole</strong>.</p></li> <li> <p>Odehraje míč před jeho <strong>přeletěním přes síť</strong>.</p></li> <li> <p>Ztratí <strong>kontrolu nad raketou</strong>.<br><br></p></li></ul> <hr> <h5><img role="img" draggable="false" src="https://s.w.org/images/core/emoji/16.0.1/svg/2705.svg" alt="✅"> Správné vrácení míče</h5> <ul> <li> <p>Míč se může <strong>dotknout sítě</strong> a zůstat platný.</p></li> <li> <p>Může se odehrát i <strong>mimo sloupky</strong>.</p></li> <li> <p>Raketa smí přeletět síť <strong>až po odehrání míče</strong>.<br><br></p></li></ul> <hr> <h5><img role="img" draggable="false" src="https://s.w.org/images/core/emoji/16.0.1/svg/23f3.svg" alt="⏳"> Plynulost hry</h5> <ul> <li> <p><strong>20 s</strong> mezi body</p></li> <li> <p><strong>90 s</strong> mezi hrami (mimo 1. hry a tie-breaky)</p></li> <li> <p><strong>120 s</strong> mezi sadami</p></li> <li> <p><strong>Rozehrávka:</strong> max. <strong>5 minut<br><br></strong></p></li></ul> <hr> <h5><img role="img" draggable="false" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f468-200d-1f3eb.svg" alt="👨‍🏫"> Koučování</h5> <ul> <li> <ul> <li> <p><strong>Zakázáno během výměn</strong> (výjimka: pauzy v týmových soutěžích).</p></li> <li> <p>Povoleno <strong>verbálně/vizuálně</strong> během střídání stran v týmových zápasech.<br><br></p></li></ul></li></ul>',
  'navody', 'Jiří Machek', false, true, '2025-08-24 16:04:46'
) on conflict (slug) do nothing;

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'jak-prihlasit-dite-na-tenisovy-turnaj-v-cr', 'Jak přihlásit dítě na tenisový turnaj v ČR', 'Chcete, aby vaše dítě začalo hrát oficiální tenisové turnaje pod Českým tenisovým svazem (ČTS)? Tento přehled vám krok za krokem ukáže, co všechno je potřeba zařídit, na co…',
  '<p>Chcete, aby vaše dítě začalo hrát oficiální tenisové turnaje pod Českým tenisovým svazem (ČTS)? Tento přehled vám krok za krokem ukáže, co všechno je potřeba zařídit, na co nezapomenout a jak celý proces funguje.</p> <hr> <h5>1. Registrace dítěte v ČTS</h5> <p>Než se dítě může přihlásit na jakýkoliv turnaj, musí mít splněné tyto podmínky:</p> <ul> <li> <p><img draggable="false" role="img" alt="✅" src="https://s.w.org/images/core/emoji/16.0.1/svg/2705.svg"> <strong>Platné ČTS ID</strong> (registrace v Českém tenisovém svazu)</p></li> <li> <p><img draggable="false" role="img" alt="✅" src="https://s.w.org/images/core/emoji/16.0.1/svg/2705.svg"> <strong>Členství v tenisovém klubu</strong>, který je součástí ČTS</p></li> <li> <p><img draggable="false" role="img" alt="✅" src="https://s.w.org/images/core/emoji/16.0.1/svg/2705.svg"> <strong>Platná lékařská prohlídka</strong> (evidovaná v systému ČTS)</p></li> <li> <p><img draggable="false" role="img" alt="✅" src="https://s.w.org/images/core/emoji/16.0.1/svg/2705.svg"> <strong>Aktivní hráčská licence</strong> (obnovuje se každý rok přes klub)</p></li></ul> <p><img draggable="false" role="img" alt="📌" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f4cc.svg"> <em>Tip:</em> Pokud vaše dítě ještě není registrováno, klub vám se vším pomůže.</p> <hr> <h5>2. Získání přístupu do systému ČTS</h5> <p>Rodič nebo starší hráč potřebuje přístup do online systému:</p> <ul> <li> <p>Navštivte: <a href="https://cztenis.cz" target="_new" rel="noopener">https://cztenis.cz</a></p></li> <li> <p>Přihlaste se jako <strong>hráč</strong> nebo <strong>zástupce hráče</strong></p></li> <li> <p>Po přihlášení můžete spravovat přihlášky na turnaje, licence a další</p></li></ul> <hr> <h5>3. Vyhledání vhodného turnaje</h5> <p>V sekci <strong>„Turnaje“</strong> si nastavte filtry podle:</p> <ul> <li> <p>věkové kategorie (např. <strong>mladší žactvo</strong>)</p></li> <li> <p>lokality a termínu</p></li> <li> <p>typu turnaje (např. <strong>oblastní C</strong>, <strong>krajský B</strong> atd.)</p></li> <li> <p>povrchu (antuka, tvrdý povrch...)</p></li></ul> <p><img draggable="false" role="img" alt="💡" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f4a1.svg"> Vyberte turnaj, který odpovídá schopnostem a možnostem dítěte.</p> <hr> <h5>4. Přihlášení na turnaj</h5> <ul> <li> <p>Klikněte na konkrétní turnaj</p></li> <li> <p>Stiskněte tlačítko <strong>„Přihlásit“</strong></p></li> <li> <p>Systém automaticky zkontroluje licenci a lékařské potvrzení</p></li> <li> <p>Po úspěšném přihlášení se hráč objeví v seznamu přihlášených</p></li></ul> <p><img draggable="false" role="img" alt="📌" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f4cc.svg"> <em>Pozor:</em> Každý turnaj má vlastní <strong>uzávěrku přihlášek</strong> – většinou úterý před víkendem, kdy se hraje.</p> <hr> <h5>5. Sledujte přijetí do turnaje</h5> <p>Po uzávěrce turnaje sledujte:</p> <ul> <li> <p>seznam <strong>přijatých hráčů</strong></p></li> <li> <p>případné <strong>náhradníky</strong></p></li> <li> <p><strong>rozlosování</strong> (většinou den před turnajem)</p></li></ul> <p><img draggable="false" role="img" alt="➡️" src="https://s.w.org/images/core/emoji/16.0.1/svg/27a1.svg"> Vše najdete buď na stránce turnaje, nebo ve svém hráčském profilu.</p> <hr> <h5>6. Den turnaje – co s sebou</h5> <p>Dostavte se na místo turnaje obvykle <strong>15–30 minut před začátkem</strong>. Přesný čas najdete v propozicích.</p> <p>S sebou mějte:</p> <ul> <li> <p>tenisové vybavení (raketa, oblečení, obuv)</p></li> <li> <p><strong>průkaz pojištěnce</strong></p></li> <li> <p><strong>svačinu a pití</strong></p></li> <li> <p>ideálně i <strong>kopii lékařské prohlídky</strong></p></li></ul> <hr> <h5>Shrnutí – co všechno je potřeba:</h5> <table> <thead> <tr> <th><img draggable="false" role="img" alt="✅" src="https://s.w.org/images/core/emoji/16.0.1/svg/2705.svg"> Požadavek</th> <th><img draggable="false" role="img" alt="📌" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f4cc.svg"> Poznámka</th></tr> </thead> <tbody> <tr> <td>Členství v klubu ČTS</td> <td>Potvrzuje klub</td></tr> <tr> <td>Aktivní hráčská licence</td> <td>Obnovuje se každoročně přes klub</td></tr> <tr> <td>Lékařská prohlídka</td> <td>Platí max. 1 rok, do systému ji zadává klub</td></tr> <tr> <td>Registrace v systému ČTS</td> <td>Přístupové údaje pro rodiče nebo hráče</td></tr> <tr> <td>Včasné přihlášení</td> <td>Uzávěrka obvykle úterý před víkendovým turnajem</td></tr> </tbody></table>',
  'navody', 'Jiří Machek', false, true, '2025-08-24 20:06:00'
) on conflict (slug) do nothing;

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'jak-reagovat-na-agresivniho-rodice-na-turnaji', 'Jak reagovat na agresivního rodiče na turnaji?', 'Sport má být radost, ale někdy se na turnajích setkáme s rodiči, kteří reagují přehnaně emotivně nebo až agresivně. V takových chvílích je důležité zachovat chladnou hlavu a…',
  '<p>Sport má být radost, ale někdy se na turnajích setkáme s rodiči, kteří reagují přehnaně emotivně nebo až agresivně. V takových chvílích je důležité zachovat chladnou hlavu a jednat tak, aby se situace neeskalovala a zároveň byla chráněna bezpečnost hráčů i atmosféra celé akce.</p> <p>Tady je doporučený postup krok za krokem:</p> <hr> <h5>1. Zachovejte klidný tón i postoj</h5> <ul> <li> <p>Mluvte klidně, nezvyšujte hlas, nepoužívejte útočný jazyk.</p></li> <li> <p>Postavte se tak, abyste měli odstup a necítili se ohroženě. Ruce mějte volně podél těla – nezkřížené.</p></li></ul> <hr> <h5>2. Oddělte emoce od faktů</h5> <ul> <li> <p>Nenechte se vtáhnout do provokací.</p></li> <li> <p>Reagujte na konkrétní problém, ne na osobní útoky.</p> <blockquote> <p>„Rozumím, že máte obavy z rozhodnutí rozhodčího, pojďme to řešit věcně.“</p></blockquote></li></ul> <hr> <h5>3. Stanovte jasné hranice</h5> <ul> <li> <p>Vyjádřete pravidla stručně a klidně.</p> <blockquote> <p>„Rozhovor můžeme vést, pokud zůstaneme slušní.“</p></blockquote></li> <li> <p>Pokud se chování nezmění, upozorněte na další krok (pořadatel, trenér).</p></li></ul> <hr> <h5>4. Neřešte to sami, pokud je situace vyhrocená</h5> <ul> <li> <p>Přizvěte kolegu, trenéra nebo pořadatele.</p></li> <li> <p>Nikdy se nesnažte rodiče „přeřvat“ nebo zastavit fyzicky.</p></li></ul> <hr> <h5>5. Myslete na bezpečnost dětí</h5> <ul> <li> <p>Pokud rodič reaguje přímo proti hráči, okamžitě dítě odveďte a přivolejte pomoc.</p></li></ul> <hr> <h5>6. Dokumentujte incident</h5> <ul> <li> <p>Zapište si datum, čas, průběh i svědky události.</p></li> <li> <p>Pokud je to vážné, informujte klub nebo organizátory turnaje.</p></li></ul> <hr> <h5><br>Příklady vhodných vět</h5> <p><strong>Pro uklidnění situace:</strong></p> <ul> <li> <p>„Rozumím, že máte obavy. Můžeme to probrat, pokud zůstaneme u věcné diskuse.“</p></li> <li> <p>„Pojďme se držet faktů, ať to společně vyřešíme.“</p></li></ul> <p><strong>Pro nastavení hranic:</strong></p> <ul> <li> <p>„Prosím, mluvte bez urážek. Jinak tento rozhovor nemůže pokračovat.“</p></li> <li> <p>„Toto chování není v souladu s pravidly turnaje. Potřebuju, abyste se uklidnil/a.“</p></li></ul> <p><strong>Pro ukončení interakce:</strong></p> <ul> <li> <p>„Tímto rozhovor končím. Pokud chcete situaci řešit, můžeme to udělat po zápase u pořadatele.“</p></li> <li> <p>„Musím vás požádat, abyste opustil/a prostor hřiště. Můžeme to probrat později mimo přítomnost dětí.“</p></li></ul> <p><strong>Pro zapojení autority:</strong></p> <ul> <li> <p>„Pokud v tomto chování budete pokračovat, budu muset zavolat pořadatele.“</p></li> <li> <p>„Vaše chování narušuje průběh turnaje. Teď je nutné, abyste se vzdálil/a.“</p></li></ul> <hr> <p><br><img draggable="false" role="img" alt="👉" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f449.svg"> Klíčem je <strong>neeskalovat konflikt</strong> a zároveň <strong>chránit prostředí, ve kterém děti sportují</strong>. Pevné, ale klidné vystupování často stačí k tomu, aby se situace uklidnila.<br><br></p>',
  'navody', 'Jiří Machek', false, true, '2025-08-28 15:01:46'
) on conflict (slug) do nothing;

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'jak-reagovat-na-cilene-podvadeni-deti-behem-zapasu', 'Jak reagovat na cílené podvádění dětí během zápasu?', 'Sport má učit férovosti a respektu, ale občas se na turnajích objeví situace, kdy někdo úmyslně porušuje pravidla – ať už jde o hráče, rodiče, trenéra nebo dokonce rozhodčího. V…',
  '<p>Sport má učit férovosti a respektu, ale občas se na turnajích objeví situace, kdy někdo <strong>úmyslně porušuje pravidla</strong> – ať už jde o hráče, rodiče, trenéra nebo dokonce rozhodčího. V takových chvílích je důležité jednat rychle, klidně a spravedlivě, aby byla chráněna atmosféra soutěže i samotné děti.</p><hr /><h5>1. Zachovejte klid a nestrannost</h5><ul><li><p>I když je situace nespravedlivá, nereagujte křikem nebo obviněním.</p></li><li><p>Mluvte o konkrétních situacích, ne o motivech.</p><blockquote><p>„Viděl jsem, že míček dopadl za čáru,“ místo „Děláte to schválně.“</p></blockquote></li></ul><hr /><h5>2. Ověřte si fakta</h5><ul><li><p><strong>Trenér:</strong> sledujte opakované situace a dělejte si stručné poznámky.</p></li><li><p><strong>Rozhodčí:</strong> konzultujte situaci s kolegou nebo nadřízeným rozhodčím.</p></li><li><p><strong>Pořadatel:</strong> zjistěte, zda je k dispozici videozáznam nebo svědci.</p></li></ul><hr /><h5>3. Zasáhněte okamžitě, ale profesionálně</h5><ul><li><p><strong>Trenér:</strong> požádejte o krátké přerušení a stručně předložte svůj postřeh rozhodčímu.</p></li><li><p><strong>Rodič:</strong> nevstupujte přímo do zápasu, ale obraťte se na pořadatele nebo trenéra.</p></li><li><p><strong>Pořadatel:</strong> při opakovaném nebo závažném podvádění můžete utkání přerušit a svolat komisi.</p></li></ul><hr /><h5>4. Chraňte děti před konfliktem</h5><ul><li><p>Nedopusťte, aby se děti staly součástí hádky mezi dospělými.</p></li><li><p>Dětem podávejte stručné a srozumitelné vysvětlení:</p><blockquote><p>„Rozhodnutí se upravilo, aby byla hra spravedlivá.“</p></blockquote></li></ul><hr /><h5>5. Používejte jasné a autoritativní formulace</h5><ul><li><p>„Podle pravidel se tato situace řeší takto…“</p></li><li><p>„Musíme hru vést spravedlivě pro všechny hráče.“</p></li><li><p>„Rozumím, že s tím nemusíte souhlasit, ale toto je oficiální rozhodnutí.“</p></li></ul><hr /><h5>6. Dokumentujte incident</h5><ul><li><p>Zapište si datum, čas, situaci, jména zúčastněných i kroky, které jste podnikli.</p></li><li><p>Pokud jde o opakované chování, informujte klub nebo sportovní svaz.</p></li></ul><hr /><h5><br /><img role="img" draggable="false" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f511.svg" alt="🔑" /> Tip: Mějte připravený „Fair play protokol“</h5><p>Nejlepší obranou proti chaosu je <strong>jasný postup předem</strong>. Pokud turnaj stanoví, co se stane při podvádění (kdo zasahuje, jaké jsou kroky), všichni vědí, na čem jsou, a nemusí reagovat ad-hoc a pod vlivem emocí.</p><p><img role="img" draggable="false" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f449.svg" alt="👉" /> Šablonu „Fair play protokolu“ si můžete <a href="https://tenishub.cz/wp-content/uploads/2025/09/fair_play_protokol.pdf"><strong>stáhnout zde.</strong></a><br /><br /></p>',
  'navody', 'Jiří Machek', false, true, '2025-08-28 15:09:37'
) on conflict (slug) do nothing;

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'jak-se-chovat-na-turnajich-a-mistracich', 'Jak se chovat na turnajích a mistrácích?', 'Na tenisových turnajích a mistrovských utkáních (tzv. mistrácích) platí trochu jiná kultura než na fotbale nebo hokeji. Tenis má dlouhou tradici fair play, ticha a respektu. Proto…',
  '<p>Na tenisových turnajích a mistrovských utkáních (tzv. mistrácích) platí trochu jiná kultura než na fotbale nebo hokeji. Tenis má dlouhou tradici fair play, ticha a respektu. Proto je důležité vědět, jak se chovat – jako divák, hráč i rodič.</p> <h5>1. Chování diváka</h5> <ul> <li> <p><strong>Ticho při hře</strong> – nemluv, netleskej a nešustěte obaly, dokud není výměna ukončena.</p></li> <li> <p><strong>Potlesk až po výměně</strong> – ocenění skvělého úderu patří oběma hráčům, nejen „tvému“.</p></li> <li> <p><strong>Žádné rady hráčům</strong> – koučování z hlediště je na většině turnajů zakázané.</p></li> <li> <p><strong>Telefon na tichý režim</strong> – jakýkoli zvuk může rušit.<br><br></p></li></ul> <h5>2. Chování hráče</h5> <ul> <li> <p><strong>Přijď včas</strong> – buď připravený k rozcvičce podle rozpisu.</p></li> <li> <p><strong>Respektuj rozhodčího</strong> – nesouhlas vyjadřuj slušně, ideálně formální žádostí o kontrolu stopy míče (na antuce).</p></li> <li> <p><strong>Nekomentuj soupeře</strong> – soustřeď se na svou hru, ne na provokace.</p></li> <li> <p><strong>Udržuj tempo hry</strong> – zbytečné zdržování je nesportovní.</p></li> <li> <p><strong>Poděkuj po zápase</strong> – podání ruky soupeři i rozhodčímu je samozřejmost.<br><br></p></li></ul> <h5>3. Chování rodiče</h5> <ul> <li> <p><strong>Podpora, ne tlak</strong> – chval snahu a nasazení, ne jen výsledky.</p></li> <li> <p><strong>Nezasahuj do hry</strong> – žádné pokřiky, komentáře ani gesta během výměn.</p></li> <li> <p><strong>Zůstaň pozitivní</strong> – negativní poznámky k rozhodčímu nebo soupeři kazí atmosféru a mohou vést k napomenutí.<br><br></p></li></ul> <h5>4. Etiketa mimo kurt</h5> <ul> <li> <p><strong>Oblečení</strong> – na kurt čisté sportovní, mimo kurt přiměřené (na oficiální akce spíš slušné).</p></li> <li> <p><strong>Respekt k areálu</strong> – neodhazuj odpadky, nevstupuj na zakázaná místa.</p></li> <li> <p><strong>Fotografie a video</strong> – jen pokud to pořadatel povolí a neruší to hráče.</p></li></ul> <p><img draggable="false" role="img" alt="💡" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f4a1.svg"> V tenisu se často říká: <em>„Leave no trace“</em> – po sobě zanech jen stopy na antuce a dobrý dojem.<br><br></p> <h5>5. Praktické rady</h5> <p><strong>Po příjezdu na turnaj</strong></p> <ul> <li> <p>Přijeď minimálně 30–45 minut před zápasem.</p></li> <li> <p>Nahlas se u pořadatele, zkontroluj rozpis a kurt.</p></li> <li> <p>Připrav si vše potřebné – míče, pití, ručník, náhradní raketu.</p></li></ul> <p><strong>Zápis utkání družstev</strong></p> <ul> <li> <p>Vyplňuje kapitán družstva, který odevzdává soupisku a pořadí hráčů.</p></li> <li> <p>Hráči by měli být na místě včas, aby nedošlo ke zbytečnému zdržování.</p></li></ul> <p><strong>Po skončení zápasu</strong></p> <ul> <li> <p>Vždy podej ruku soupeři i rozhodčímu.</p></li> <li> <p>Zkontroluj, že výsledek je správně zapsaný.</p></li> <li> <p>Rodiče i trenéři: nejdřív oceňte snahu, teprve později řešte chyby.</p></li></ul>',
  'navody', 'Jiří Machek', false, true, '2025-08-28 15:20:02'
) on conflict (slug) do nothing;

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'pravidla-minitenisu-prvni-krok-deti-k-velkemu-tenisu', 'Pravidla minitenisu: první krok dětí k velkému tenisu', 'Minitenis je zjednodušená forma tenisu pro děti, obvykle ve věku 5–8 let. Pravidla i vybavení jsou přizpůsobené tak, aby se děti učily techniku, pohyb po kurtu a koordinaci…',
  '<p>Minitenis je zjednodušená forma tenisu pro děti, obvykle ve věku 5–8 let. Pravidla i vybavení jsou přizpůsobené tak, aby se děti učily techniku, pohyb po kurtu a koordinaci zábavnou a přístupnou formou – bez frustrace z těžkých míčů nebo vysoké sítě.</p> <h5>1. Hřiště</h5> <ul> <li> <p><strong>Velikost:</strong> zmenšený kurt, obvykle polovina klasického (cca 8,23 × 11–12 m).</p></li> <li> <p><strong>Síť:</strong> nižší než standardní, kolem 80–85 cm.</p></li> <li> <p><strong>Vymezení:</strong> používají se kužely, pásky nebo speciální čáry.</p></li></ul> <h5>2. Míče</h5> <ul> <li> <p><strong>Typ:</strong> měkčené, větší, s nižším odskokem – tzv. červené míče.</p></li> <li> <p><strong>Rychlost:</strong> asi o 75 % pomalejší než běžné tenisové míče.</p></li></ul> <h5>3. Rakety</h5> <ul> <li> <p><strong>Délka:</strong> kratší, 43–58 cm (17–23 palců) podle věku a výšky dítěte.</p></li> <li> <p><strong>Hmotnost:</strong> lehké, aby se daly snadno ovládat.</p></li></ul> <h5>4. Hra</h5> <ul> <li> <p><strong>Podání:</strong> obvykle spodem (podhoz), často se začíná „na rozehru“ bez ostrého servisu.</p></li> <li> <p><strong>Počet odskoků:</strong> platí maximálně 1 odskok, stejně jako v klasickém tenise.</p></li> <li> <p><strong>Bodování:</strong> různé varianty – krátké sety do 7 bodů nebo časově omezené zápasy (např. 10 minut).</p></li> <li> <p><strong>Výhodová pravidla:</strong> většinou <em>no-ad scoring</em> (při 40:40 rozhoduje jeden míč).</p></li> <li> <p><strong>Flexibilita:</strong> u nejmenších dětí se míč může i chytit a odhodit, aby se trénovala koordinace.</p></li></ul> <h5>5. Cíle minitenisu</h5> <ul> <li> <p>Rozvoj <strong>koordinace, citu pro míč a pohybu na hřišti</strong>.</p></li> <li> <p>Učení správné <strong>úderové techniky</strong> při nižší rychlosti hry.</p></li> <li> <p>Podpora <strong>zábavy a spolupráce</strong> – pravidla jsou pružná a mají motivovat děti k radosti ze hry.</p></li></ul> <h5>6. Hlavní rozdíly oproti dospělému tenisu</h5> <ul> <li> <p><strong>Menší hřiště</strong> – hraje se na čtvrtinu kurtu.</p></li> <li> <p><strong>Nižší síť</strong> – aby děti snadno přehodily míček.</p></li> <li> <p><strong>Speciální míčky</strong> – měkké, pomalejší, označené červenou barvou.</p></li> <li> <p><strong>Zkrácené zápasy</strong> – např. do 10 bodů, při 9:9 rozhoduje „náhlá smrt“.</p></li> <li> <p><strong>Formát utkání</strong> – vítězí ten, kdo vyhraje 2 ze 3 sad; hrají spolu chlapci i dívky.</p></li></ul> <hr> <p><br><img draggable="false" role="img" alt="👉" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f449.svg"> Správné vybavení je klíčové – těžší raketa nebo rychlý míč může dítě odradit. Proto se na soutěžích pečlivě hlídá, aby se používaly červené míče a lehké rakety odpovídající věku hráčů.</p> <p>Minitenis je především o tom, aby si děti tenis zamilovaly. Výsledky přijdou později – hlavní je radost ze hry.&nbsp;<br><br></p>',
  'navody', 'Jiří Machek', false, true, '2025-08-28 15:36:17'
) on conflict (slug) do nothing;

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'stredni-kurt-prechod-mezi-minitenisem-a-babytenisem', 'Střední kurt: přechod mezi minitenisem a babytenisem', 'Kategorie „střední kurt“ je důležitým mezistupněm mezi minitenisem a babytenisem. Dětem umožňuje plynule zvládnout skok z malého hřiště na regulérní tenisový kurt – a to bez…',
  '<p>Kategorie <strong>„střední kurt“</strong> je důležitým mezistupněm mezi minitenisem a babytenisem. Dětem umožňuje plynule zvládnout skok z malého hřiště na regulérní tenisový kurt – a to bez zbytečné fyzické zátěže či špatných technických návyků.<br></p> <h5>1. Cíle středního kurtu</h5> <ul> <li> <p>Usnadnit dětem z minitenisu (6–7 let) přechod do babytenisu (8–9 let).</p></li> <li> <p>Poskytnout prostor pro všechny základní údery i první taktické prvky.</p></li> <li> <p>Umožnit technický rozvoj bez nadměrného tlaku na fyzickou kondici.</p></li></ul> <h5>2. Věkové doporučení</h5> <ul> <li> <p>Typicky pro děti <strong>7–8 let</strong>, dle rozhodnutí trenéra a výkonnosti hráče.</p></li></ul> <h5>3. Parametry kurtu</h5> <ul> <li> <p><strong>Šířka:</strong> standardní (8,23 m).</p></li> <li> <p><strong>Délka:</strong> zkrácena na <strong>18,29 – 20,12 m</strong> (oproti 23,77 m u plného kurtu).</p></li> <li> <p><strong>Síť:</strong> standardní výška 0,914 m.</p></li> <li> <p>Úprava: zkrácení délky pomocí čáry rovnoběžné se základní čárou, posunuté o 1,83 – 2,74 m dovnitř.</p></li></ul> <h5>4. Vybavení</h5> <ul> <li> <p><strong>Míče:</strong> oranžové (s odskokem redukovaným o cca 50 %).</p></li> <li> <p><strong>Rakety:</strong> délka 23–25 palců.</p></li></ul> <h5>5. Formát hry</h5> <ul> <li> <p>Skupiny 3–5 hráčů (s možností postupu do vyřazovací části – pavouka).</p></li> <li> <p>Nejčastější formáty:</p> <ul> <li> <p>2 vítězné tiebreaky (do 7 nebo 10 bodů), nebo</p></li> <li> <p>od stavu 2:2 jeden set, při 6:6 tiebreak.</p></li></ul></li></ul> <h5>6. Výhody pro vývoj hráče</h5> <ul> <li> <p><strong>Plynulý přechod</strong> z minitenisu na standardní kurt.</p></li> <li> <p><strong>Technický rozvoj:</strong> správný švih, zakončení úderů, hra na síti.</p></li> <li> <p><strong>Prevence špatných návyků:</strong></p> <ul> <li> <p>příliš dlouhé hraní minitenisu (→ omezený prostor, podhmaty, absence švihu),</p></li> <li> <p>příliš brzký babytenis (→ fyzická nezralost, problémy s podáním či ukončením míče).</p></li></ul></li> <li> <p><strong>Respekt k biologickému věku</strong> a individuálnímu tempu vývoje každého dítěte.</p></li></ul> <hr> <p><br><img draggable="false" role="img" alt="👉" src="https://s.w.org/images/core/emoji/16.0.1/svg/1f449.svg">&nbsp;Střední kurt funguje jako ideální <strong>„mezistanice“</strong> – dítě si osvojuje techniku i taktiku v prostředí, které je pro něj přirozené a motivující. Díky tomu je přechod do babytenisu hladký a bez frustrace.&nbsp;<br><br></p> <p></p>',
  'navody', 'Jiří Machek', false, true, '2025-08-28 15:46:48'
) on conflict (slug) do nothing;

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'babytenis-zakladni-pravidla-a-format-hry', 'Babytenis: základní pravidla a formát hry', 'Babytenis představuje přechodnou fázi mezi dětským minitenisem a klasickým dospělým tenisem. Děti už hrají na plný kurt a přes regulérní síť, ale pravidla i vybavení jsou stále…',
  '<p>Babytenis představuje přechodnou fázi mezi dětským minitenisem a klasickým dospělým tenisem. Děti už hrají na plný kurt a přes regulérní síť, ale pravidla i vybavení jsou stále lehce upravené, aby zvládly techniku i fyzickou zátěž.</p> <h5>1. Hřiště a síť</h5> <ul> <li> <p><strong>Celý kurt:</strong> hraje se na standardní velikost, bez zmenšení.</p></li> <li> <p><strong>Síť:</strong> v regulérní výšce, takže děti se učí to samé, co využijí později v dospělém tenise.</p></li></ul> <h5>2. Míče</h5> <ul> <li> <p><strong>Typ:</strong> speciální míče se zelenou tečkou nebo pruhem (<em>soft</em>).</p></li> <li> <p><strong>Vlastnosti:</strong> jsou lehčí, méně natlakované, skáčou pomaleji a níž než běžné míče.</p></li></ul> <h5>3. Formát zápasu</h5> <ul> <li> <p>Nejčastěji se hraje <strong>jeden set do 4 gemů</strong>, při stavu 3:3 následuje <strong>tiebreak do 7 bodů</strong>.</p></li> <li> <p>Někdy se hraje <strong>set do 6 gemů</strong>, při 6:6 pak tiebreak.</p></li> <li> <p><strong>Pořadatel turnaje</strong> určuje přesný formát.</p></li></ul> <h5>4. Kategorie a složení hráčů</h5> <ul> <li> <p>Hrají spolu i proti sobě <strong>chlapci a dívky</strong>.</p></li> <li> <p>Soutěží se jak ve <strong>dvouhrách (singlech)</strong>, tak ve <strong>čtyřhrách (deblech)</strong>, často i ve smíšených družstvech.</p></li></ul> <h5>5. Cíle babytenisu</h5> <ul> <li> <p><strong>Rozvoj techniky:</strong> hráči si upevňují základní údery a přidávají pokročilejší prvky.</p></li> <li> <p><strong>Taktické myšlení:</strong> děti se učí přemýšlet, kam a jak míč zahrát, aby získaly výhodu.</p></li> <li> <p><strong>Pozvolný přechod:</strong> ideálně přes tzv. <em>střední kurt</em>, aby rozdíl mezi minitenisem a plným hřištěm nebyl tak náhlý.</p></li></ul> <h5>6. Důležitá doporučení</h5> <p>Použití klasických dospělých míčů v této kategorii je nevhodné – jsou příliš těžké a rychlé, mají vysoký odskok a mohou vést k technickým chybám nebo dokonce ke zranění. Proto je babytenis jasně vymezenou kategorií s vlastním vybavením.</p>',
  'navody', 'Jiří Machek', false, true, '2025-08-28 15:55:42'
) on conflict (slug) do nothing;

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'pravidla-velkeho-tenisu-dospeli', 'Pravidla velkého tenisu (dospělí)', 'Tenis je jedním z nejpopulárnějších sportů na světě. Přestože se může zdát složitý, jeho základní pravidla jsou jasná a logická. Tady najdeš přehled toho nejdůležitějšího, co by…',
  '<p>Tenis je jedním z nejpopulárnějších sportů na světě. Přestože se může zdát složitý, jeho základní pravidla jsou jasná a logická. Tady najdeš přehled toho nejdůležitějšího, co by měl znát každý hráč i divák.<br /><br /></p><h5>1. Základní vybavení a hřiště</h5><ul><li><p>Kurt má rozměry:</p><ul><li><p>pro dvouhru: 23,77 × 8,23 m</p></li><li><p>pro čtyřhru: 23,77 × 10,97 m</p></li></ul></li><li><p>Síť je uprostřed vysoká 91,4 cm.</p></li><li><p>Hraje se míčem schváleným ITF a raketou libovolné velikosti dle pravidel.</p></li></ul> <h5>2. Zahájení hry</h5><ul><li><p>O podání a stranu kurtu se losuje (mincí nebo míčkem). V nižších soutěžích často kámen–nůžky–papír.</p></li><li><p>Hráč podává střídavě z pravé a levé strany. Začíná se vždy z pravé.</p></li><li><p>Míč musí dopadnout do diagonálního podávacího pole soupeře.</p></li></ul> <h5>3. Skórování</h5><ul><li><p>Pořadí bodů: 0 (love) – 15 – 30 – 40 – game.</p></li><li><p>Stav 40:40 = shoda (deuce). Pro vítězství ve hře je nutné získat 2 body po sobě (výhoda – advantage).</p></li><li><p>Set vyhrává hráč, který získá 6 her s rozdílem alespoň 2 (např. 6:4).</p></li><li><p>Při stavu 6:6 se obvykle hraje tiebreak (první na 7 bodů s rozdílem 2).</p></li><li><p>Zápas se hraje obvykle na 2 vítězné sety (ženy, většina mužských turnajů) nebo 3 vítězné sety (muži na grandslamech).</p></li></ul> <h5>4. Průběh výměny</h5><ul><li><p>Podávající má na každý míček dva pokusy (první a druhý servis).</p></li><li><p>Míč musí dopadnout do kurtu soupeře (čára se počítá jako dobrý míč).</p></li><li><p>Výměna končí, pokud:</p><ul><li><p>míč dopadne mimo hřiště,</p></li><li><p>míč se dotkne sítě a spadne mimo,</p></li><li><p>hráč zahraje míč do sítě a ten nepřejde,</p></li><li><p>hráč udělá chybu (dvojchyba při podání, dotyk sítě, chycení míče rukou apod.).</p></li></ul></li></ul> <h5>5. Strany a změny</h5><ul><li><p>Hráči si mění strany kurtu po každém lichém počtu gamů (1., 3., 5. atd.).</p></li><li><p>Pauza mezi gamy je 90 sekund, mezi sety 2 minuty.</p></li></ul> <h5>6. Speciální pravidla</h5><ul><li><p><strong>Let servis</strong>: pokud podání trefí síť, ale dopadne do správného pole → hraje se znovu bez trestu.</p></li><li><p><strong>Dvojchyba</strong>: dva nepovedené servisy → bod pro soupeře.</p></li><li><p><strong>Čtyřhra</strong>: platí širší kurt (včetně postranních čar pro čtyřhru).</p></li></ul>',
  'navody', 'Jiří Machek', false, true, '2025-09-04 20:11:55'
) on conflict (slug) do nothing;

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'uvod-k-blogu-rodice-rodicum', 'Úvod k blogu „Rodiče rodičům“', 'Rodiče rodičům je nová blogová série určená všem, kteří se ocitli ve světě tenisových kurtů díky svým dětem – často bez toho, aby tušili, co je čeká. Tenis je krásný, ale pro…',
  '<p><b>Rodiče rodičům</b> je nová blogová série určená všem, kteří se ocitli ve světě tenisových kurtů díky svým dětem – často bez toho, aby tušili, co je čeká.<br />Tenis je krásný, ale pro začátečníka může být i nepřehledný, plný nových pojmů, neznámých situací a otázek, na které vám nikdo nepřipravil odpovědi.<br />Tyto články vznikly proto, že přesně tak jsme se cítili na začátku i my.<br />Ne jako trenéři. Ne jako profesionálové. Ale jako rodiče, kteří chtějí svému dítěti porozumět, podpořit ho a zároveň se v tenisovém světě<br />neztratit.</p> <p>Blog přináší:</p> <ul> <li>skutečné příběhy rodičů z úplných začátků,</li> <li>psychologické vhledy do dětského vývoje a emocí při sportu,</li> <li>praktické rady založené na realitě (ne teoriích),</li> <li>vysvětlení situací, které rodiče často řeší poprvé v životě,</li> <li>propojení s trenérským pohledem – lidsky a srozumitelně.</li></ul> <p>Cílem není radit, jak trénovat.<br />Cílem je provést rodiče cestou, kterou si většina z nás prošla:<br />od prvního tréninku, přes první turnaje, první krize, první vybavení, až po první tým a první ambice.</p> <p>Chceme rodičům dát pocit, že v tom nejsou sami. A dětem pomoci tím, že jejich rodiče budou klidnější, informovanější a citlivější k tomu, co jejich malý sportovec potřebuje.</p> <p>Pokud máš nápad na téma, otázku nebo situaci, která by tě zajímala – ozvi se.<br />Tento blog je živý, bude se průběžně doplňovat a přizpůsobovat přesně tomu, co rodiče skutečně řeší.</p> <p></p>',
  'navody', 'Jiří Machek', false, true, '2025-11-24 23:20:30'
) on conflict (slug) do nothing;

insert into public.articles (slug,title,perex,body,category,author_name,is_sample,published,created_at) values (
  'rodice-rodicum-dil-1-jak-zacit-s-tenisem-kdyz-rodice-sami-tenis-neznaji', '„Rodiče rodičům“ DÍL 1 – Jak začít s tenisem, když rodiče sami tenis neznají', 'Příběh malé Aničky a její rodiny je typickým příkladem toho, co zažívají tisíce rodičů po celé republice. Dítě projeví zájem o tenis, rodiče chtějí podpořit jeho nadšení, ale sami…',
  '<p>Příběh malé Aničky a její rodiny je typickým příkladem toho, co zažívají tisíce rodičů po celé republice. Dítě projeví zájem o tenis, rodiče chtějí podpořit jeho nadšení, ale sami nevědí, kde začít. A není to chyba – tenisový svět je mnohem složitější a barevnější, než se na první pohled zdá. Minitenis, babytenis, závody, různé přístupy trenérů, rozdíly mezi kluby, vhodné vybavení… To vše rodiče často objevují až postupně během prvních měsíců a let.</p> <hr /> <h5>Výběr rakety – víc než jen technický parametr</h5> <p>Výběr první tenisové rakety je často úplně jiný proces, než si rodiče představují. U malých hráčů totiž nejde pouze o technické vlastnosti, jako je délka rámu nebo hmotnost. Děti vnímají svět silně vizuálně a emocionálně – barvy, tvar, pocit v ruce nebo dokonce to, jak raketa působí při držení, může ovlivnit jejich chuť hrát i samotné sebevědomí.</p> <p>Aničky první raketa byla úplně obyčejná – jedna z nejlevnějších, kterou jsme ve sportovním obchodě našli. A přesto byla „ta pravá“. Ne proto, že by byla technicky dokonalá, ale prostě se jí líbila. Byla barevná, lehká a Anička ji hrdě nosila všude s sebou. V tomto věku je estetická stránka pro dítě výrazně důležitější, než si dospělí často uvědomují.</p> <p>Postupem času ale přišla přirozená potřeba výměny. Ruka sílila, technika se zlepšovala, údery byly rychlejší. A tak začala cesta hledání „té další nejlepší“ rakety. A tady jsme pochopili, jak důležitá je kombinace dvou věcí: dítěti se raketa musí líbit – a zároveň musí technicky odpovídat jeho velikosti a schopnostem.</p> <p>U Aničky tak každá nová raketa byla malým rituálem. Nejprve výběr vzhledu: barvy, značka, tvar. Pak teprve přicházeli na řadu dospělí – aby zajistili, že raketa je skutečně vhodná, bezpečná, správně dlouhá a lehká.</p> <p>A to je moment, kde v naší tenisové škole přebírá roli trenér. Ten zná parametry dětského vývoje, ví, jak má raketa sedět v ruce, a dokáže odhadnout, jaký model dítěti pomůže rozvíjet techniku, ne ji brzdit. Rodiče tak nejsou odkázáni na náhodu nebo rychlé nákupy v obchodě.</p> <p>Akademie nabízí dvě možnosti – trenér může doporučit a prodat ideální raketu, nebo ji dítěti zapůjčit. Díky půjčovně mohou malí hráči vyzkoušet více modelů, postupně měnit velikosti a najít takovou raketu, která sedí nejen technicky, ale i emocionálně. Rodiče se tak vyhnou zbytečným výdajům a dítě dostane přesně to, co potřebuje.</p> <p>Je důležité, aby dítě k nové raketě nemělo negativní emoci. Některé děti dokonce dokážou výkon přičítat raketě – „s touhle mi to nejde, ona je hnusná“. Takové propojení pocitu a výkonu je u dětí zcela běžné. Proto je důležité, aby při prvním kontaktu cítily zvědavost, příjemný pocit v ruce a chuť ji vyzkoušet.</p> <p>Zkušení trenéři poznají během několika minut, zda dítěti raketa sedí. Sledují držení, napětí v ruce, pocit stability i to, jak dítě reaguje na první odpaly. Dobře zvolená raketa dokáže dětskou techniku posunout dopředu – špatně zvolená ji naopak může dlouhodobě brzdit.</p> <hr /> <h5>Jak jsme vybírali tenisovou školu</h5> <p>Na začátku jsme hledali prostředí, kde se bude Anička cítit bezpečně, kde se nebude bát, kde ji povedou lidé, kteří rozumí dětem stejně dobře jako tenisu. Nešlo nám o výkon, o rychlé výsledky ani o ambice. Hledali jsme trenéry, kteří budují dlouhodobý vztah ke sportu a vědí, že nejdřív musí přijít radost – teprve potom výkonnost.</p> <h5>Tip pro rodiče – Jak poznat dobrou tenisovou školu</h5> <p>I jako úplný laik poznáte, jak klub pracuje. Sledujte, zda jsou děti na tréninku aktivní, zda trenér dokáže vysvětlovat jednoduše a laskavě, zda opravuje konkrétní věci a zda dítě zažívá úspěch i při učení. Důvěryhodná tenisová škola má jasnou koncepci výuky, otevřeně komunikuje s rodiči, neprodává nereálné sliby a respektuje individualitu dítěte. Co je nejdůležitější – dítě z tréninku odchází spokojené a těší se na další.</p> <p>Nás zaujal přístup trenérů v Tenisové a Fitness Akademii MS GEM. Kladli důraz na všestrannost, kondici, týmovost a radost. Byli nejen trenéry, ale skutečnými pedagogy, kteří uměli přiblížit sport tak, aby si ho děti zamilovaly.</p> <hr /> <h5>První tréninky – krok za krokem, bez spěchu</h5> <p>Anička začala trénovat dvakrát týdně individuálně, aby se mohla postupně naučit základní pohybové a tenisové dovednosti. Malé děti potřebují klidné tempo, jasné instrukce a pocit, že se jim daří. Učí se držet raketu, hledat kontakt s míčem, vnímat rovnováhu, správně stát, skákat, pracovat s tělem a hlavně – chápat, že trénink je místo, kde se zkouší, chybuje a učí.</p> <h5>Jak se malé děti učí tenis – pohled trenéra</h5> <p>Výuka techniky u malých dětí začíná jednoduchými úkoly: hodem míčku, chycením, odpalem po odskoku. Forhend se učí zprvu bez rotace, jen s důrazem na kontakt a stabilitu. Bekhend bývá zpočátku slabší, protože vyžaduje silnější zapojení trupu – ale postupně se stává spolehlivým úderem. Podání je nejpomaleji se rozvíjející dovednost, protože vyžaduje koordinaci, klid a trpělivost. Nic z toho nelze uspěchat. Upevňuje se postupně, týden po týdnu, často i několik měsíců.</p> <p>Po několika týdnech bylo vidět, že se Anička zlepšuje. Forehned začal mít směr, bekhend jistotu. Podání však zůstávalo velkou výzvou – v minitenisu má dítě pouze jeden pokus, a to vytváří značný psychický tlak. Učila se s emocemi pracovat, dýchat, soustředit se.</p> <hr /> <h5>První klubové turnaje – strach, nadšení a velké oči</h5> <p>Po třech měsících přišla pozvánka na klubový turnaj. Pro rodiče byl zdrojem obav, pro Aničku směsicí nadšení a nejistoty. A to je přirozené. Klubový turnaj je první příležitostí, kdy dítě zažije atmosféru soutěže – ale zároveň také uvidí, že tenis není jen trénink. Je to místo, kde se potkává s ostatními dětmi, zažívá úspěchy, ale také drobná zklamání, která utvářejí jeho sportovní charakter.</p> <h5>Jak to chodí na klubových turnajích – vysvětlení pro rodiče</h5> <p>Každý klub má své vlastní postupy – liší se přihlašování, pravidla i atmosféra. Domácí prostředí dítěti pomáhá, protože zná kurt, trenéry i další děti. Turnaj zároveň ukazuje trenérům, jak dítě reaguje pod tlakem, jak dodržuje pravidla a jak pracuje s emocemi. Pro dítě jsou tyto turnaje klíčovým zážitkem – díky nim roste sebevědomí i motivace.</p> <hr /> <h5>Neoficiální turnaje v okolí – další cenné zkušenosti</h5> <p>Po klubových turnajích jsme začali jezdit i na neoficiální turnaje pořádané okolními kluby. A to byl další obrovský krok vpřed. Každý turnaj měl jinou atmosféru – někde dělali společnou rozcvičku, jinde jej vedli hravou formou s tréninkovými prvky, a některé kluby turnaje pojaly velmi soutěžně. Tato pestrost byla klíčová. Anička se naučila reagovat v různých podmínkách, což je důležitá součást vývoje mladého hráče.</p> <h5>Proč jezdit na neoficiální turnaje?</h5> <p>Dítě získá zkušenosti, které mu žádný trénink nenahradí. Učí se pracovat s nervozitou, měnit taktiku podle soupeře, vnímat prostředí, zvládat tlak i radovat se z maličkostí. Tyto turnaje rozvíjejí odolnost, přizpůsobivost i sportovní odvahu.</p> <hr /> <h5>Únava – skrytý soupeř, který ovlivňuje každý výkon</h5> <p>Únava je často tím největším protivníkem, kterého dítě na turnaji potká. Může být fyzická i psychická, někdy obojí. Dlouhé čekání mezi zápasy, horko, hluk, nové prostředí, nepředvídatelné situace – to vše dítěti bere energii.</p> <h5>Proč je správná svačina, pití a odpočinek tak důležitý?</h5> <p>Malé děti spalují energii mnohem rychleji než dospělí. Když se k tomu přidá stres, tělo se vyčerpává dvojnásobně. Pravidelný pitný režim, lehká svačina (ovoce, rohlík se sýrem, jogurt), výměna propoceného trička a krátká pauza na odpočinek dokážou výkon stabilizovat a obnovit psychickou pohodu. Únava není známkou slabosti – je to přirozená reakce těla.</p> <hr /> <h5>Podpora mimo trénink a jak poznat, co je pro moje dítě nejlepší</h5> <p>Anička měla od úplného začátku silnou potřebu být na kurtu i mimo pravidelné tréninky. Byla to její radost, její způsob, jak sdílet úspěchy s rodiči. Často vzala raketu, doběhla za tátou a nadšeně zvolala: „Táto, pojď se podívat, co už umím!“</p> <p>Tyto momenty nebyly o drilu, ale o radosti. Trénink navíc vznikl přirozeně z jejího nadšení, ne z tlaku nebo povinnosti.</p> <p>Postupně však přišlo jiné období. Tréninků, turnajů a emocí bylo hodně. Najednou začala říkat: „Teď nechci na tenis. Chci si stavět Lego.“ Nebo chtěla jít ven s kamarády. Je to úplně přirozené – dětská psychika potřebuje odpočinek, změnu prostředí a možnost volně přepínat mezi aktivitami. Někdy je to dokonce znakem zdravého vývoje: dítě si umí samo říct, kdy má dost.</p> <p>A dnes? Prochází další fází vývoje. Ráno si sedne k snídani a řekne: „Táto, vezmi mě na kurt. Já se chci zlepšit. Chci je dohnat.“ Vnímá, že roste, že se zlepšuje, a chce dál. Její motivace je vnitřní – už nejde jen o hru, ale o touhu posouvat vlastní hranice. A to je v dětském sportu ten nejcennější motor.</p> <p>Každé dítě má jiný temperament, motivaci i způsob učení. Některé děti po tréninku ještě běží s raketou ven a chtějí pokračovat. Jiné si potřebují odpočinout, hrát si, kreslit nebo prostě vypnout. Ani jedna varianta není špatně. Je potřeba pochopit, co dítěti jeho vývoj dovoluje, a co mu dělá dobře.</p> <p>Děti ve věku 4–10 let jsou velmi citlivé na pochvalu a vnitřní motivaci. Nepotřebují výkon – potřebují pocit, že něčeho dosáhly a že je někdo vidí. Pokud dítě samo prosí o trénink navíc, je to znak radosti a pocitu úspěchu. Stačí pak přidat krátké hravé aktivity: pinkání, házení míčku, soutěže na přesnost.</p> <p>Naopak pokud dítě po tréninku říká, že nechce dál hrát, nebo se o tenisu nechce bavit, znamená to psychickou únavu. Děti jsou výkonné, ale neumí dlouho potlačovat přetížení. V takové fázi je dobré sport nechat být a dopřát dítěti volnost. V dlouhodobém horizontu se tím posílí jeho sebevědomí.</p> <p>Velmi časté je i to, že dítě chce „někoho dohnat“. Vidí kamaráda, který už hraje rychleji, nebo lépe podává, a touží být jako on. To je zdravá motivace – pokud nepřichází z tlaku dospělých. V takovém případě pomůže krátká domácí hra, ale stále hravou formou, bez soupeření uvnitř rodiny.</p> <p>A pak jsou děti, které tenis milují, ale je to jen jeden z jejich koníčků. Baví je plavání, kreslení, jízda na kole, hudba… A to je v pořádku. V jejich vývoji je důležitá pestrost, ne specializace. Takové dítě nepotřebuje více tréninku – potřebuje více radosti.</p> <p>To, kolik času dítě věnuje tenisu mimo trénink, je individuální. Každé dítě má jiné tempo zrání, jiný typ motivace a jiný způsob, jak prožívá úspěchy i těžší chvíle. Úkolem rodiče není tlačit – ale citlivě pozorovat. Vidět, kdy dítě chce víc, a kdy naopak potřebuje ubrat.</p> <hr /> <h5>Tým, kamarádi a první sezona družstev – okamžik, kdy se vše propojí</h5> <p>Zařazení do týmu bylo pro Aničku velkým milníkem. Už to nebyl jen trénink nebo kroužek. Byl to svět. Děti si vytvořily partu, rodiče komunitu a společné víkendy v hale nebo na antuce se staly součástí života. Díky družstvům pochopila, že tenis není jen individuální sport – ale také týmová podpora, spolupráce a společné emoce.</p> <h5>Tenis jako týmová hra – jak to funguje?</h5> <p>Možná překvapí, že i minitenis má svou týmovou soutěž. Dokonce i Mistrovství České republiky. Děti soutěží v týmech, střídají se v zápasech, povzbuzují se a učí se odpovědnosti. Týmový tenis je pro děti velmi důležitý – díky němu se učí, že nejsou na hřišti samy, že mají oporu a že jejich výkon může pomoci ostatním.</p> <hr /> <h5>Letní kempy – místo, kde děti rostou nejrychleji</h5> <p>První letní kemp byl pro Aničku nezapomenutelný. Nebyl to jen tenisový tábor – byl to týden, který z ní udělal samostatnější, sebejistější a radostnější osobnost. Tréninky, hry, společné obědy, odpolední program, soutěže… děti jsou v kempu doslova ponořené do sportovního života.</p> <h5>Proč jsou tenisové kempy tak přínosné?</h5> <p>Kempy nejčastěji pořádají tenisové kluby nebo akademie, ale existují i specializované kempy mimo domovský klub. Účast na klubovém kempu je skvělá pro upevnění vztahů s trenéry i kamarády. Kempy mimo klub přináší nové zkušenosti – dítě vidí jiný styl výuky, jiné děti, jiné prostředí. To podporuje adaptabilitu, odvahu a sebevědomí. Právě díky kempům děti často zažijí nejrychlejší růst výkonnosti.</p> <hr /> <h5>Závěr DÍLU 1</h5> <p>První roky přinesl Aničce obrovský pokrok – první technické údery, první zápasy, první vítězství i první slzy. Získala nové kamarády, první sportovní sebevědomí a hlavně vztah k tenisu, který v ní vydržel. A to je pro začátek ta nejcennější výhra.</p>',
